function formatCompletedDuration(
    seconds
) {

    const total =
        Math.max(
            0,
            Number(seconds) || 0
        );

    const hours =
        Math.floor(
            total / 3600
        );

    const minutes =
        Math.floor(
            (total % 3600) / 60
        );

    const secs =
        Math.floor(
            total % 60
        );

    return (
        `${String(hours).padStart(2, "0")}:` +
        `${String(minutes).padStart(2, "0")}:` +
        `${String(secs).padStart(2, "0")}`
    );
}

function formatLabourTotal(
    totalSeconds
) {

    const hours =
        Math.floor(
            totalSeconds / 3600
        );

    const minutes =
        Math.floor(
            (totalSeconds % 3600) / 60
        );

    return (
        `${String(hours).padStart(2, "0")}h ` +
        `${String(minutes).padStart(2, "0")}m`
    );
}


function isSameLocalDay(
    dateA,
    dateB
) {

    return (
        dateA.getFullYear() ===
            dateB.getFullYear() &&
        dateA.getMonth() ===
            dateB.getMonth() &&
        dateA.getDate() ===
            dateB.getDate()
    );
}


function isInCurrentWeek(
    date
) {

    const now =
        new Date();

    const start =
        new Date(
            now.getFullYear(),
            now.getMonth(),
            now.getDate()
        );

    const day =
        start.getDay();

    const diff =
        day === 0
            ? -6
            : 1 - day;

    start.setDate(
        start.getDate() + diff
    );

    start.setHours(
        0, 0, 0, 0
    );

    const end =
        new Date(start);

    end.setDate(
        end.getDate() + 7
    );

    return (
        date >= start &&
        date < end
    );
}


function syncCompletedJobsFromStore() {

    if (
        !window.ShiftDynamicsStore ||
        typeof window.ShiftDynamicsStore.getJobs !==
            "function"
    ) {
        return;
    }

    const sharedCompleted =
        window.ShiftDynamicsStore
            .getJobs()
            .filter(
                job =>
                    job.status ===
                        "Completed" &&
                    job.assignment
                        ?.mechanicName ===
                        COMPLETED_MECHANIC_NAME
            );


    completedJobs.length =
        0;


    sharedCompleted.forEach(
        job => {

            const completedAt =
                job.repair?.completedAt
                    ? new Date(
                        job.repair.completedAt
                    )
                    : null;

            const labourSeconds =
                Number(
                    job.repair?.labourSeconds ||
                    0
                );


            completedJobs.push({
                id:
                    String(
                        job.jobCardNumber
                    ).replace(
                        /^#/,
                        ""
                    ),

                vehicle:
                    [
                        job.vehicle?.make,
                        job.vehicle?.model
                    ]
                        .filter(Boolean)
                        .join(" ") ||
                    "Vehicle",

                plate:
                    job.vehicle?.plate ||
                    "--",

                service:
                    job.serviceConcern ||
                    "Workshop Service",

                completed:
                    completedAt
                        ? completedAt.toLocaleString()
                        : "--",

                completedAt:
                    completedAt
                        ? completedAt.toISOString()
                        : null,

                duration:
                    formatCompletedDuration(
                        labourSeconds
                    ),

                labourSeconds:
                    labourSeconds,

                bay:
                    job.assignment?.bay ||
                    job.repair?.bay ||
                    "--",

                mechanic:
                    COMPLETED_MECHANIC_NAME,

                started:
                    job.repair?.startedAt
                        ? new Date(
                            job.repair.startedAt
                        ).toLocaleTimeString(
                            [],
                            {
                                hour:
                                    "2-digit",
                                minute:
                                    "2-digit"
                            }
                        )
                        : "--",

                ended:
                    completedAt
                        ? completedAt.toLocaleTimeString(
                            [],
                            {
                                hour:
                                    "2-digit",
                                minute:
                                    "2-digit"
                            }
                        )
                        : "--",

                result:
                    "Completed",

                notes:
                    job.repair?.notes ||
                    "Job completed."
            });
        }
    );
}


function renderCompletedStats() {

    const section =
        completedJobsList
            ?.closest("section");

    if (!section) {
        return;
    }


    function findCompletedStat(
        labelText
    ) {

        const label =
            [...section.querySelectorAll("span")]
                .find(
                    item =>
                        item.textContent
                            .trim() ===
                        labelText
                );

        return (
            label
                ?.parentElement
                ?.querySelector("strong") ||
            null
        );
    }


    const todayValue =
        findCompletedStat(
            "Completed Today"
        );

    const weekValue =
        findCompletedStat(
            "This Week"
        );

    const labourValue =
        findCompletedStat(
            "Labour Today"
        );


    const now =
        new Date();


    const validJobs =
        completedJobs.filter(
            job => {

                if (!job.completedAt) {
                    return false;
                }

                const completedDate =
                    new Date(
                        job.completedAt
                    );

                return !Number.isNaN(
                    completedDate.getTime()
                );
            }
        );


    const todayJobs =
        validJobs.filter(
            job => {

                const completedDate =
                    new Date(
                        job.completedAt
                    );

                return (
                    completedDate.getFullYear() ===
                        now.getFullYear() &&
                    completedDate.getMonth() ===
                        now.getMonth() &&
                    completedDate.getDate() ===
                        now.getDate()
                );
            }
        );


    const weekStart =
        new Date(
            now.getFullYear(),
            now.getMonth(),
            now.getDate()
        );

    const currentDay =
        weekStart.getDay();

    const mondayOffset =
        currentDay === 0
            ? -6
            : 1 - currentDay;

    weekStart.setDate(
        weekStart.getDate() +
        mondayOffset
    );

    weekStart.setHours(
        0,
        0,
        0,
        0
    );


    const weekEnd =
        new Date(
            weekStart
        );

    weekEnd.setDate(
        weekEnd.getDate() + 7
    );


    const weekJobs =
        validJobs.filter(
            job => {

                const completedDate =
                    new Date(
                        job.completedAt
                    );

                return (
                    completedDate >=
                        weekStart &&
                    completedDate <
                        weekEnd
                );
            }
        );


    const labourSeconds =
        todayJobs.reduce(
            (total, job) =>
                total +
                Number(
                    job.labourSeconds ||
                    0
                ),
            0
        );


    if (todayValue) {

        todayValue.textContent =
            String(
                todayJobs.length
            ).padStart(
                2,
                "0"
            );
    }


    if (weekValue) {

        weekValue.textContent =
            String(
                weekJobs.length
            ).padStart(
                2,
                "0"
            );
    }


    if (labourValue) {

        labourValue.textContent =
            formatLabourTotal(
                labourSeconds
            );
    }
}


